from collections import OrderedDict
from typing import Any, Dict, List, Optional


def simulate_ttl_lru(capacity: int, events: List[Dict[str, Any]]) -> List[Optional[Any]]:
    if capacity < 0:
        raise ValueError("capacity must be non-negative")

    # key -> (value, expires_at)
    cache: "OrderedDict[str, tuple[Any, int]]" = OrderedDict()
    results: List[Optional[Any]] = []

    def purge(current_time: int) -> None:
        # spec: before each event, delete entries with time >= expires_at
        while cache:
            k = next(iter(cache))
            _, expires_at = cache[k]
            if current_time >= expires_at:
                cache.popitem(last=False)
            else:
                break

    for ev in events:
        op = ev.get("op")
        t = ev.get("time")

        purge(t)

        if op == "put":
            if capacity == 0:
                continue

            key = ev["key"]
            value = ev["value"]
            ttl = ev["ttl"]
            expires_at = t + ttl

            # write/overwrite and mark MRU
            if key in cache:
                cache.pop(key, None)
            cache[key] = (value, expires_at)

            # LRU eviction only; do not do additional purge within this event.
            while len(cache) > capacity:
                cache.popitem(last=False)

        elif op == "get":
            key = ev["key"]
            if key not in cache:
                results.append(None)
            else:
                value, _ = cache[key]
                cache.move_to_end(key, last=True)
                results.append(value)
        else:
            raise ValueError(f"Unknown op: {op}")

    return results

from typing import List


def decode_frames_by_chunk(chunks: List[str], max_frame_size: int) -> List[List[str]]:
    if not isinstance(max_frame_size, int) or max_frame_size < 0:
        raise ValueError("max_frame_size must be a non-negative integer")

    if chunks is None:
        raise ValueError("chunks must not be None")

    # Buffer for bytes not yet processed (across chunk boundaries)
    buf = bytearray()

    out: List[List[str]] = [[] for _ in range(len(chunks))]

    def append_decoded_payload(payload_bytes: bytes, idx: int):
        out[idx].append(payload_bytes.hex())

    # Process each chunk sequentially
    for i, chunk_hex in enumerate(chunks):
        # Decode current chunk hex string into bytes (or empty)
        if not isinstance(chunk_hex, str):
            raise ValueError("each chunk must be a hex string")

        if len(chunk_hex) % 2 != 0:
            raise ValueError("hex string must contain an even number of characters")

        try:
            if chunk_hex == "":
                chunk_bytes = b""
            else:
                chunk_bytes = bytes.fromhex(chunk_hex)
        except ValueError as e:
            raise ValueError("illegal hex") from e

        buf.extend(chunk_bytes)

        # Consume as many complete frames as possible from buf
        while True:
            if len(buf) < 4:
                break

            payload_len = int.from_bytes(buf[0:4], byteorder="big", signed=False)
            if payload_len > max_frame_size:
                raise ValueError("declared payload length exceeds max_frame_size")

            if len(buf) < 4 + payload_len:
                break

            # Extract payload
            start = 4
            end = 4 + payload_len
            payload = bytes(buf[start:end])

            # Remove consumed frame
            del buf[:end]

            # Zero-length payload must output empty string when header completes
            append_decoded_payload(payload, i)

    # After all chunks, ensure no incomplete header/payload remains
    if len(buf) != 0:
        raise ValueError("incomplete header/payload at end of input")

    return out

def process_idempotent_transfers(initial_balances, events):
    # Validate initial_balances
    if not isinstance(initial_balances, dict):
        raise ValueError("initial_balances must be a dict")

    balances = {}
    for k, v in initial_balances.items():
        if not isinstance(k, str) or not k:
            raise ValueError("account names must be non-empty strings")
        if not isinstance(v, int) or v < 0:
            raise ValueError("initial balances must be non-negative integers")
        balances[k] = v

    if not isinstance(events, list):
        raise ValueError("events must be a list")

    id_cache = {}  # id -> {"payload": payload_dict, "result": result_dict}
    results = []

    def _validate_event(ev):
        if not isinstance(ev, dict):
            raise ValueError("each event must be a dict")

        required_keys = {"id", "from", "to", "amount"}
        if set(ev.keys()) != required_keys:
            raise ValueError("each event must contain exactly keys: id, from, to, amount")

        event_id = ev["id"]
        from_acct = ev["from"]
        to_acct = ev["to"]
        amount = ev["amount"]

        if not isinstance(event_id, str) or not event_id:
            raise ValueError("id must be a non-empty string")
        if not isinstance(from_acct, str) or not from_acct:
            raise ValueError("from must be a non-empty string")
        if not isinstance(to_acct, str) or not to_acct:
            raise ValueError("to must be a non-empty string")
        if from_acct == to_acct:
            raise ValueError("from and to must be different")
        if not isinstance(amount, int) or amount <= 0:
            raise ValueError("amount must be a positive integer")

        return {"id": event_id, "from": from_acct, "to": to_acct, "amount": amount}

    for ev in events:
        payload = _validate_event(ev)
        event_id = payload["id"]

        if event_id in id_cache:
            cached = id_cache[event_id]["payload"]
            if (
                cached["from"] != payload["from"]
                or cached["to"] != payload["to"]
                or cached["amount"] != payload["amount"]
            ):
                raise ValueError("conflicting id payload")
            # Return cached result without re-executing
            results.append(dict(id_cache[event_id]["result"]))
            continue

        from_acct = payload["from"]
        to_acct = payload["to"]
        amount = payload["amount"]

        from_balance = balances.get(from_acct, 0)
        to_balance = balances.get(to_acct, 0)

        if from_balance < amount:
            result = {
                "id": event_id,
                "status": "rejected",
                "from_balance": from_balance,
                "to_balance": to_balance,
            }
            id_cache[event_id] = {"payload": payload, "result": result}
            results.append(dict(result))
        else:
            # Apply transfer
            from_balance_after = from_balance - amount
            to_balance_after = to_balance + amount
            balances[from_acct] = from_balance_after
            balances[to_acct] = to_balance_after

            result = {
                "id": event_id,
                "status": "applied",
                "from_balance": from_balance_after,
                "to_balance": to_balance_after,
            }
            id_cache[event_id] = {"payload": payload, "result": result}
            results.append(dict(result))

    return {"results": results, "balances": balances}
